export function getPromptBySlug(slug: string): Prompt | undefined {
  return prompts.find((p) => p.slug === slug);
}

export function getPromptsByCategory(categorySlug: string): Prompt[] {
  return prompts.filter((p) => p.category === categorySlug);
}

export function getFeaturedPrompts(): Prompt[] {
  return prompts.filter((p) => p.featured);
}

export function getRelatedPrompts(prompt: Prompt, limit = 4): Prompt[] {
  const sameCategory = prompts.filter(
    (p) => p.id !== prompt.id && p.category === prompt.category
  );
  const sharedTags = prompts.filter(
    (p) =>
      p.id !== prompt.id &&
      p.category !== prompt.category &&
      p.tags.some((t) => prompt.tags.includes(t))
  );
  return [...sameCategory, ...sharedTags].slice(0, limit);
}

export const allModels = Array.from(
  new Set(prompts.flatMap((p) => p.models))
).sort();

export function getCategoryPromptCount(categorySlug: string): number {
  return prompts.filter((p) => p.category === categorySlug).length;
}

export const allTags = Array.from(
  new Set(prompts.flatMap((p) => p.tags))
).sort();
